import Foundation

enum GuanyinModernReading {
    static func sections(for lot: GuanyinLot) -> [(String, String)] {
        let keyword = lot.theme.components(separatedBy: "：").first ?? lot.title
        let focus = perspective(lot.theme)
        return [
            ("整体解译", lot.theme + "\n\n" + "这支签借「" + lot.title + "」的故事提供一个观察入口。读诗时，可以先留意哪种处境与你眼前的问题相似，再想想哪些地方并不相同。传统故事中的转折是叙事，并不会按同样顺序发生在每个人身上。\n\n" + focus.0),
            ("本签精髓", keyword + "\n\n" + focus.1 + "\n\n给自己一个检验问题：接下来出现怎样的事实，我会愿意调整原来的判断？把答案写出来，比反复寻找同一个肯定更能帮助选择。"),
            ("凡事做事", "先把当前的问题写成一句能回答的话，例如“这周要不要开始试做”，而不是笼统地问“以后会不会成功”。接着分清已经发生的事实、自己的推测，以及尚未得到的信息。把别人的评价和你的实际需要分开，才更容易看见选择。\n\n挑一个成本可控的尝试，写清用多少时间、投入多少资源、做到哪一步就回看。试过以后记录真实反馈：哪项假设被证实，哪项需要修改。暂停、求助或换方法，都可以是认真做事的一部分。" + "\n\n" + application(lot.theme, domain: 0)),
            ("爱情婚姻", "可以先问自己：我期待的是陪伴、确认关系、修复信任，还是被理解？把期待说得具体，比猜测对方的沉默更有帮助。单身时留意相处是否轻松、表达是否被尊重；有伴侣时，找一个双方都愿意交流的时刻，谈一件具体的事。\n\n若正处于争执或分离，先确认双方是否都愿意继续沟通，再谈修复。用“发生了什么、我有什么感受、我希望怎样调整”代替指责。签文不能替任何人作出承诺；是否靠近、复合或离开，仍应由真实互动、意愿与边界决定。" + "\n\n" + application(lot.theme, domain: 1)),
            ("工作求职 · 创业事业", "把“想换一种生活”进一步拆成岗位内容、收入安排、成长空间和工作方式。求职前核实职位要求，准备能说明能力的具体作品或经历；创业前先接触真实需求，弄清谁愿意为怎样的价值付费，而非只凭热情推测市场。\n\n若遇到停滞，回看阻力来自技能、信息、资源，还是合作方式。选一项能补足的环节，给它一个有限的尝试周期。涉及离职、合伙或大额投入时，把交接、权责和退路写清；不要把一次拒绝当作整条道路的结论。" + "\n\n" + application(lot.theme, domain: 2)),
            ("考试竞赛 · 升迁竞选", "先找到真实的考核标准，再安排准备。学习时用一次练习发现具体薄弱点，把“我不行”换成“这一类题的哪个步骤还不熟”。准备比赛或晋升时，整理可被验证的成果，并了解评审关注的能力，而非只比较他人的进度。\n\n把剩余时间分给复习、练习和回看错误，留出调整余地。遇到不懂的地方可以向老师、同伴或主管提出一个明确问题。结果出来以后分别记录有效的方法和需要改进的地方；一次名次或评审，只反映这一次条件下的表现。" + "\n\n" + application(lot.theme, domain: 3)),
            ("投资理财", "先分清这笔钱的用途、预计使用时间，以及出现损失后会影响哪些生活安排。把产品说明、费用、退出条件和信息来源逐项看清；凡是自己说不明白的收益机制，都值得继续核实，而不是用签的等第补上信心。\n\n如果你发现自己急于翻本、追赶别人，或只愿意看支持买入的信息，可以先暂停操作，整理已经承担的风险。把疑问交给合适的持牌专业人士讨论。这里不提供买卖信号、收益承诺或市场时机预测，实际选择应建立在真实资料上。" + "\n\n" + application(lot.theme, domain: 4)),
            ("经商生意", "先找一位真实客户，听他描述问题、已有替代方式和愿意承担的成本。把产品价值说成一句清楚的话，再以有限范围验证。整理收款、支出、交付周期和未履行的承诺，区分看起来热闹的咨询与真正完成的交易。\n\n合作时提前约定交付内容、验收方式、付款节点和退出安排。若反馈不如预期，尝试只改变一个因素，便于判断原因。不要为了证明原来的判断正确而持续扩大投入；是否继续，应看实际需求、执行条件与可承受的成本。" + "\n\n" + application(lot.theme, domain: 5)),
            ("房地交易", "把自住需要、租住安排和投资期待分别写清，确认位置、通勤、居住体验与资金安排之间的取舍。查看房屋与合同资料时，把不理解的项目列成问题，向对应的专业人士核实；不要仅凭介绍者的口头承诺补齐未知信息。\n\n对比不同方案时，同时记录一次性支出、持续费用、时间成本以及无法按计划推进时的安排。签署之前给自己留出阅读和咨询的时间。签文不能判断价格走势或交易结果，这一节只帮助你把需要核实的事项摆到桌面上。" + "\n\n" + application(lot.theme, domain: 6)),
            ("健康与照顾", "把身体上的实际感受和读到签文后的担心分开记录：何时开始、有什么变化、哪些事情让你感到困扰。与专业人员交流时，可以带上已有记录与想问的问题，让沟通更清楚。传统疾病断语属于旧时文本，不能用于诊断或判断你的病情。\n\n在日常照顾上，先看看自己是否需要休息、有人陪伴，或有人代办琐事。若有身体不适或健康疑问，按实际情况寻求医疗帮助，并保留已有的诊疗安排。不要根据签文自行改变用药、检查或治疗，也无需为抽到某种等第承担额外恐惧。" + "\n\n" + application(lot.theme, domain: 7)),
            ("转换变更", "改变之前，先说清你希望离开的是什么、希望靠近的又是什么。把保持现状和作出改变各自的收益、代价、不确定之处列出来。有时需要的是调整一个环节，有时确实需要换环境；给自己比较多种路径的空间。\n\n挑一个可撤回的小步骤体验变化，再决定是否扩大。写下过渡期需要的时间、帮助与资源，以及什么信号会让你暂停或回退。如果选择暂时不变，也可以设一个重新评估的日期，让等待成为有意识的安排，而不是无限拖延。" + "\n\n" + application(lot.theme, domain: 8)),
            ("求孕求子", "先识别自己此刻最需要的是信息、陪伴，还是缓解外界催促。有关备孕、孕期或生育的疑问，可以整理成一张问题清单，交由合适的医疗专业人员结合实际情况解答。签文不能预测受孕时间、胎儿情况、性别或孕产结果。\n\n如果家人的期待令你有压力，可以提前准备一句边界清楚的话，例如“这件事我们会按自己的情况安排，有需要会主动告诉你”。与伴侣讨论能提供的实际支持，让照顾落到分工与陪伴。任何结果都不应被解释成你是否虔诚或是否足够努力。" + "\n\n" + application(lot.theme, domain: 9)),
            ("官司诉讼", "把事情按时间顺序写清，区分亲身经历、已有材料和未经核实的说法。整理合同、往来记录及相关通知，保留原有材料；对不理解的要求或文件，记下问题和实际收到的日期，便于向专业人士完整说明情况。\n\n在需要时寻求有资质的法律帮助，确认适用于具体事项的程序、期限与可选路径。是否协商或采取其他行动，应基于真实事实和专业意见。传统签语不能判断胜负，也不应让你忽略正式通知或仅因“吉签”而扩大冲突。" + "\n\n" + application(lot.theme, domain: 10)),
            ("寻人寻物", "先从最后一次确认的时间、地点和经过开始，把确定线索与记忆猜测分开。寻找物品时可按路线逐处回看，联系可能接触过的场所，并记下已经查过哪里，避免焦虑中反复检查同一处。不要把签里的方位当成定位结果。\n\n涉及找人时，留意对方隐私，使用可信且合适的联系渠道，不向陌生账号支付所谓寻人保证金。若涉及失联者安全或其他紧急情况，优先联系当地有关部门。签文中的“归来”“迟见”不能说明实际下落或承诺找回。" + "\n\n" + application(lot.theme, domain: 11)),
            ("远行出国", "把出行目的、时间、预算和同行安排写清，再逐项核实证件、交通、住宿及目的地的实际要求。确认资料来自可信渠道，对尚未办妥的事项留出处理时间。若行程变化，知道可以联系谁、怎样调整，比追求完全没有意外更实用。\n\n准备一份自己与可信赖的人都能找到的必要联系信息，按实际需要安排备选路线。若你犹豫的是离开熟悉环境，先分清对未知的担心与真正的现实限制。这支签只提供思考视角，不判断旅途吉凶，也不替代最新的出行信息。" + "\n\n" + application(lot.theme, domain: 12))
        ]
    }
    private static func perspective(_ theme: String) -> (String, String) {
        if theme.contains("修复") || theme.contains("重建") || theme.contains("重逢") {
            return ("若你正在考虑回头或重新开始，可以先辨认：值得保留的是什么，过去让你受伤或受阻的条件有没有改变。重新连接不等于回到原样；让新的约定、分工和边界有真实的位置，才有机会形成不同的相处方式。", "先辨认仍然存在的基础，再检查破裂的原因有没有得到处理。可以怀念过去，也可以选择新的安排；修复需要双方意愿与实际变化，不能靠一个人的坚持完成。")
        }
        if theme.contains("等待") || theme.contains("时机") || theme.contains("积累") || theme.contains("耐心") {
            return ("进展缓慢时，可以把暂时无法推动的条件与仍能准备的部分分开。给等待设一个回看日期，并在这段时间里补足一项基础。若新的事实表明原路已经不合适，调整方向也不等于之前的准备没有价值。", "等待有两种样子：一种只是承受不确定，另一种是在有限时间里积累信息与能力。试着让后者多一点，同时为自己保留改变计划的权利。")
        }
        if theme.contains("合作") || theme.contains("协作") || theme.contains("托付") || theme.contains("信任") {
            return ("当事情涉及他人时，不妨把默契变成可讨论的约定。谁负责什么、怎样反馈、出现分歧时如何处理，都值得提前说清。信任可以从一次小而可靠的履约开始，不需要立即交出全部决定权。", "把愿望、责任和权限对齐，让彼此知道可以期待什么。真诚与核实可以同时存在；提出问题不是拒绝合作，而是在为合作寻找更稳妥的基础。")
        }
        if theme.contains("风险") || theme.contains("退路") || theme.contains("边界") || theme.contains("克制") {
            return ("如果眼前处境让你想靠一次果断行动摆脱不安，先看看哪些后果可以承受、哪些承诺难以撤回。把安全、资源和选择权放进考虑，并向可靠的人核实信息。谨慎不是对自己失去信心，而是让行动有可持续的条件。", "先保护重要的底线，再讨论行动的幅度。允许自己说暂时不、少投入一点或换一条路，不必用超出承受范围的代价证明决心。")
        }
        if theme.contains("观察") || theme.contains("核实") || theme.contains("成见") || theme.contains("判断") {
            return ("试着暂时放下最初的解释，给同一件事列出另一种可能。找一个可以查证的细节，听听不同立场的描述，再决定哪些信息值得采信。看见更多并不要求你赞同所有人，而是让原有判断有机会被补充。", "把看见的事实与赋予它的解释分开。对一个关键未知多问一句，对一个熟悉结论少下定论；新的证据出现时，允许自己的看法跟着更新。")
        }
        return ("把故事转成自己的问题时，先确认你真正希望守住的东西，再看行动所需的资源是否到位。选择一个能观察结果的小步骤，留意过程中自己的感受和现实反馈。进展与停顿都可以提供信息，无需把每次波动解释成命运的提示。", "从已有条件出发，让愿望落到可以说明、可以尝试、可以回看的行动上。肯定自己的用心，也给不确定的部分留空；你不需要先知道全部答案才迈出小小一步。")
    }
    private static func application(_ theme: String, domain: Int) -> String {
        let isRepair = theme.contains("修复") || theme.contains("重建") || theme.contains("重逢")
        let isWait = theme.contains("等待") || theme.contains("积累") || theme.contains("时机")
        if domain == 1 {
            return isRepair ? "对应这支签的修复意象：与其急着回到从前，更值得谈清楚上次的问题将怎样避免，以及双方各愿意做出哪一个改变。" : isWait ? "对应这支签的节奏：允许关系在双方舒服的速度里展开，不用靠催促获得确定感，也不必无期限等待一个不愿回应的人。" : "可以把这次阅读化成一次倾听：先询问对方的真实想法，再说明自己的需要，让两种感受都有被听见的空间。"
        }
        let cues = [
            "今天的落点：先查清一项关键未知，再决定行动的大小。",
            "给关系留一个问题：彼此是否都拥有表达不同意见的空间？",
            "一个工作检查点：你所承担的责任，是否配有相应的资源与权限？",
            "把努力变得可见：找出一处具体进步，而不只盯着最后的名次。",
            "面对金钱的不确定，可以先把不理解的条款列出来，再谈是否投入。",
            "经营中的一个小验证：确认一位真实客户愿意为什么付费。",
            "关于居住的取舍，不妨先选出一项你最不愿牺牲的日常需要。",
            "此刻能做的照顾，也包括请别人替你分担一点生活上的琐事。",
            "给变化留一个检查日期，届时凭新信息重新评估，不用今天就保证到底。",
            "关于生育的节奏，你和伴侣的感受与实际需要值得被认真听见。",
            "涉及争议时，先把事实材料整理清楚，再决定如何表达诉求。",
            "寻找过程中可以记录已查过的线索，把反复担心变成有序核对。",
            "出发前给自己留一项备用安排，让变化发生时仍有可选的下一步。"
        ]
        return cues[domain]
    }
}
